  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://iliabeauty.com/en-fr/pages/affiliates', 'official_site', 'affiliate', 'ILIA''s own affiliate page states ''Earn 10% commission rate for each sale (excluding gift cards)'', a 30-day cookie window, bonuses for high-performing affiliates, exclusive offers and free samples for select partners, with sign-up via the program link on the page. No cap on total earnings is stated anywhere on the page, so the cap is recorded as unknown.', 'verified', now());
