  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 18, 14, 10, 8, 5, '{"compensation": "10% headline rate published on the brand''s own page; Impact contract terms vary by SKU and customer type (5%/10%/30%), and no cap statement is published.", "contact_access": "Open sign-up through the brand''s own affiliate page into Impact; no partnerships email is published.", "credibility": "Prestige clean-beauty leader founded in 2011 and based in Laguna Beach, with wide Sephora distribution.", "niche_fit": "Skincare-infused makeup (skin tints, mascara, lip) is core beauty-UGC territory with highly demonstrable products.", "opportunity_availability": "Affiliate applications are open via the brand''s page with exclusive offers and samples for select partners.", "ugc_evidence": "2,507 creators all time and 197 sponsored posts in 12 months on Beacons, plus a structured affiliate program with bonuses and product seeding."}'::jsonb);
