  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/cocoeve/', 'affiliate_network', 'affiliate', 'LinkClicky lists Coco & Eve''s affiliate program on Impact; FMTC''s merchant feed also lists Coco&Eve on Impact (#17345). Snippet''s check of the brand''s own pages (November 17, 2026) concludes ''Apply to Coco & Eve Affiliate Program on Impact. That is the creator route Coco & Eve publishes'', and that the brand publishes no PR email. No cap on earnings is stated, so the cap is recorded as unknown.', 'publicly_reported', now());
