  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 14, 5, 9, 8, 4, '{"compensation": "Commission exists on Impact but published figures conflict irreconcilably (2% / 15% / 5-10%), so no rate is recorded and compensation scores low.", "contact_access": "The brand''s own help centre routes creators to AspireIQ; no PR or partnerships email is published.", "credibility": "Founded in 2018, sold in ~40 countries through Sephora, Ulta and Boots; majority stake acquired by Gauge Capital in 2024.", "niche_fit": "Hair masques, tanning foams and body products with strong visual results \u2014 proven social-first UGC categories.", "opportunity_availability": "Affiliate and partner applications are open with no follower minimum stated on the pages checked.", "ugc_evidence": "Two structured creator routes: an Impact affiliate program and brand partnerships run through AspireIQ from the brand''s own help centre."}'::jsonb);
