  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/frank-body/', 'affiliate_network', 'affiliate', 'LinkClicky lists Frank Body''s affiliate program on the Impact platform, with commission shown as tiered figures ''5%-9% per sale, 11% per sale'' and no explanation of what the tiers correspond to. No cap on earnings is stated, so the cap is recorded as unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://merchants.sovrn.com/merchants/124437/frank-body-affiliate-program', 'affiliate_network', 'affiliate', 'Sovrn Commerce''s Frank Body merchant page states that the brand''s current participation, immediate access and merchant-specific terms ''could not be independently verified'' through Sovrn. Combined with the unexplained tier figures on the Impact listing, no single commission rate is recorded (rate null); the Impact listing is the qualifying route and current terms should be confirmed inside Impact at sign-up.', 'needs_review', now());
