  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://goop.com/affiliateprogram/', 'official_site', 'affiliate', 'goop''s own affiliate program page states ''Earn up to 15% affiliate commission on net sales'' with a 14-day cookie window, instructs creators and publishers to ''apply to be our partner on Commission Junction'', and gives goop@dreamday.la for affiliate inquiries. No cap on total earnings is stated, so the cap is recorded as unknown (''up to 15%'' is a rate ceiling, not an uncapped statement).', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/goop/', 'affiliate_network', 'affiliate', 'LinkClicky lists goop on CJ Affiliate with a 2% per-sale base listing, and Lasso''s category data shows a 2% to 12% range — actual earnings vary by product category and tier under the brand''s published ''up to 15%'' ceiling. The recorded rate is the brand''s own published ceiling figure.', 'publicly_reported', now());
