  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 12, 14, 13, 8, 5, '{"compensation": "Up to 15% on net sales published on the brand''s own page (CJ base listing is 2%, with a 2-12% category range reported), so realized rates vary; no cap statement published.", "contact_access": "Published affiliate inquiries email (goop@dreamday.la) plus the program page on the brand''s own site \u2014 strong contact access.", "credibility": "One of the best-known US lifestyle brands, founded by Gwyneth Paltrow, with its own retail stores and product lines.", "niche_fit": "The GOOP Beauty line fits beauty UGC, but goop is a multi-brand lifestyle retailer, so the fit is broader and less focused than a single-line beauty brand.", "opportunity_availability": "Creator and publisher applications are open via Commission Junction.", "ugc_evidence": "A formal affiliate program recruited from the brand''s own site through CJ Affiliate; no hard creator count was published on fetched pages."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Stand4 Socks', 'https://www.stand4socks.com', 'UK sock brand selling fun, giftable socks in hundreds of designs — city collections, sports, pets and seasonal gifting. Its model is buy one, give one: every pair sold donates a pair of antibacterial socks to someone experiencing homelessness in the UK, with 850,000+ pairs donated so far, 7,000+ reviews and a 4.8 rating on Trustpilot.', 'United Kingdom', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fashion'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin', 10, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://www.stand4socks.com/en-de/pages/corporate-gifting-registration.', 'https://www.stand4socks.com/en-de/pages/corporate-gifting-registration', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Stand4 Socks Affiliate Partner Program (Awin)', 'https://www.stand4socks.com/en-de/pages/corporate-gifting-registration', 'https://www.stand4socks.com/en-de/pages/corporate-gifting-registration', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.stand4socks.com/en-de/pages/corporate-gifting-registration', 'official_site', 'affiliate', 'Stand4''s official affiliate partner page (fetched in full): affiliates earn 10% commission on new customers and 5% on repeat orders, free to join, tracked and paid reliably through Awin, with ready-made creatives, seasonal campaigns and dedicated support. Its FAQ answers ''How much commission can I earn?'' with ''You earn 10% on every new customer you refer and 5% on returning customers. There''s no cap on how much you can earn.'' — the explicit no-cap statement behind the uncapped mark. Joining is Apply through Awin, brand review, then tracked links.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.stand4socks.com/en-de/pages/corporate-gifting-registration', 'official_site', 'company_background', 'The same official page states the buy-one-give-one model (a pair of antibacterial socks donated to someone experiencing homelessness in the UK for every pair sold), 850,000+ pairs donated, 7,000+ reviews rated 4.8 on Trustpilot, and free UK delivery on orders over £35. ''Who can apply?'' lists content creators, bloggers, social and email partners, deal and cashback sites and cause-aligned communities with a UK audience.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 16, 17, 6, 9, 5, '{"compensation": "10% on new customers and 5% on repeat orders via Awin, and the official FAQ explicitly states there is no cap on how much you can earn \u2014 a verified uncapped program.", "contact_access": "No affiliate email is published on the fetched page; contact runs through the Awin application and the brand''s partner review.", "credibility": "Rates, the no-cap statement and the application route are all on the brand''s own page, fetched in full.", "niche_fit": "Giftable, design-led socks are easy, low-ticket fashion UGC with a built-in social-impact story.", "opportunity_availability": "Free to join through Awin now; the brand reviews and approves qualified partners.", "ugc_evidence": "The page explicitly recruits content creators, bloggers and social partners and supplies ready-made creatives and seasonal campaigns; no creator counts are published, so saturation stays unknown."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Encircled', 'https://encircled.ca', 'Toronto, Canada women''s clothing brand founded by Kristi Soomer, making sustainable, versatile capsule-wardrobe essentials — lounge wear and athleisure from naturally derived, biodegradable fabrics. Its whole collection is sewn in Toronto, and its Awin profile reports an average order value of $275+.', 'Canada', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fashion'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'press@encircled.ca', null, 'https://www.encircled.ca/pages/faq-new', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://ui.awin.com/merchant-profile/92953.', 'https://ui.awin.com/merchant-profile/92953', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Encircled Affiliate Program', 'https://ui.awin.com/merchant-profile/92953', 'https://ui.awin.com/merchant-profile/92953', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.encircled.ca/pages/faq-new', 'official_site', 'affiliate', 'Encircled''s official FAQ has an Affiliate Program section: ''We selectively work with Affiliates who are aligned with our values. If you''ve got an audience and like what we''re about, we''d love to work with you to share our message, products, and brand.'' The same page says it loves hearing from new bloggers and influencers and gives press@encircled.ca for collaborations. No rate or cap statement appears on the brand''s own pages, so the cap is honestly unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/92953', 'affiliate_network', 'affiliate', 'Encircled''s Awin merchant profile states: ''Our average order value is $275+ and our commission is 10%'', with a 30-day attribution period.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/encircled/', 'third_party_listing', 'affiliate', 'LinkClicky lists Encircled at the same 10% per sale with a 30-day cookie but names ShareASale as the platform — the rate is corroborated across both listings while the network conflicts, so Awin (the network''s own merchant profile) is recorded and the conflict is flagged here.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.encircled.ca/pages/faq-new', 'official_site', 'company_background', 'The official FAQ states Encircled''s office is in west Toronto, 100% of its collection is made and sewn in Toronto, Canada, around 55-60% of fabrics are knit and dyed locally, and the company was started by Kristi Soomer.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 13, 17, 11, 7, 4, '{"compensation": "10% commission on a $275+ average order value (Awin''s own merchant profile) is strong per-conversion pay for fashion; LinkClicky corroborates 10% via a different network listing.", "contact_access": "Published collaboration email (press@encircled.ca) plus a general contact email on the official FAQ.", "credibility": "The program''s existence is confirmed on the brand''s own FAQ and the rate on the network''s merchant profile; one network conflict (ShareASale vs Awin) is recorded, not hidden.", "niche_fit": "Sustainable capsule wardrobe and travel-friendly basics \u2014 a direct fit for slow-fashion and minimalist-wardrobe creators.", "opportunity_availability": "Live program, but the brand says it works with affiliates selectively, so approval is not automatic.", "ugc_evidence": "The brand itself solicits bloggers and influencers on its FAQ; no creator counts are published, so saturation stays unknown."}'::jsonb);
