  insert into public.brands (name, website, description, country, status) values ('Vivobarefoot', 'https://www.vivobarefoot.com', 'London, United Kingdom barefoot footwear brand making minimalist shoes for training, outdoor and everyday wear, built around natural foot movement. It sells through its UK and US storefronts and runs its affiliate program through Awin (Affiliate Window).', 'United Kingdom', 'published') returning id into bid;
