  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin', 6, 'Commission cap: not stated in any published source found — needs review. Creator saturation: low (see evidence). Rate as reported by https://www.vivobarefoot.com/us/affiliates.', 'https://www.vivobarefoot.com/us/affiliates', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Vivobarefoot Affiliate Program (Awin)', 'https://www.vivobarefoot.com/us/affiliates', 'https://www.vivobarefoot.com/us/affiliates', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.vivobarefoot.com/us/affiliates', 'official_site', 'affiliate', 'Vivobarefoot''s official affiliates page (fetched in full) states it works with ''a network called Affiliate Window'' (Awin), offers ''industry-leading commission on sales - up to 6%'' with a 30-day cookie, exclusive offers and dedicated account management, and publishes the contact email affiliates@vivobarefoot.com. No cap statement is published, so the cap is honestly unknown; the recorded 6% is the published ceiling of the up-to rate.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://universe.beacons.ai/brands/vivobarefoot', 'third_party_listing', 'creator_saturation', 'Beacons Universe (page fetched in full, updated November 9, 2026) counts just 146 creators mentioning Vivobarefoot all time, only 12 of them in the last 30 days, 329 public posts in the last 12 months and only 8 sponsored posts in the last 12 months — small absolute numbers for an established footwear brand, which is the hard evidence behind the low-saturation mark. The same page places the brand in London, United Kingdom.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 17, 12, 14, 9, 5, '{"compensation": "Up to 6% on the brand''s own page is a modest ceiling, partly offset by premium shoe prices and a 30-day cookie.", "contact_access": "Named affiliate email (affiliates@vivobarefoot.com) and dedicated account management on the official page.", "credibility": "Program terms verified on the brand''s own page; saturation counted on Beacons Universe.", "niche_fit": "Barefoot training and outdoor footwear is a devoted niche with strong review and transition-story UGC.", "opportunity_availability": "Live, joinable via Awin signup from the official page.", "ugc_evidence": "Beacons shows an active but small creator footprint \u2014 146 creators all time and only 8 sponsored posts in 12 months \u2014 real creator activity with low saturation."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('AONIJIE', 'https://www.aonijie.com', 'Chinese trail running, hiking and road running gear manufacturer founded in 2011, specialising in hydration vests, running backpacks, trekking poles and technical apparel. It is the official UTMB World Series hydration pack supplier and sells in 94 countries; its US store runs the affiliate program.', 'China', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fitness'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'UpPromote', 20, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://www.aorunningstore.us/affiliate-program-2/.', 'https://www.aorunningstore.us/affiliate-program-2/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'AONIJIE Affiliate Program', 'https://www.aorunningstore.us/affiliate-program-2/', 'https://www.aorunningstore.us/affiliate-program-2/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.aorunningstore.us/affiliate-program-2/', 'official_site', 'affiliate', 'The brand''s official US-store affiliate page (fetched in full) offers 20% commission on every sale made through an affiliate link or coupon code, a 90-day cookie, free joining with no fees or minimum sales requirements, real-time tracking and a dedicated affiliate support team. Its FAQ answers ''How much can I earn?'' with ''There is no cap on earnings — the more you promote, the more you earn.'' — the explicit statement behind the uncapped mark. The page welcomes content creators, runners, outdoor enthusiasts, bloggers and influencers, and its assets are served from UpPromote''s CDN, indicating the program runs on UpPromote.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.aonijie.com/index.html', 'official_site', 'company_background', 'AONIJIE''s official global site describes it as a Chinese trail running, hiking and road running accessories and apparel manufacturer founded in 2011, the official UTMB World Series hydration pack supplier, with products available in 94 countries.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 16, 20, 6, 9, 4, '{"compensation": "20% on every sale with a 90-day cookie is the highest clean published rate in this batch, and the official FAQ explicitly states there is no cap on earnings \u2014 verified uncapped.", "contact_access": "A dedicated affiliate support team is promised on the page, but no email is published; the application form is the route in.", "credibility": "Rate, cookie and the no-cap statement are all on the brand''s own store page, fetched in full; the platform (UpPromote) is indicated by the page''s own asset hosting rather than a published statement.", "niche_fit": "Hydration vests and trail gear are core kit for trail-running and ultra creators, with UTMB credibility behind the brand.", "opportunity_availability": "Open application form on the official page, free, with applications reviewed for brand alignment.", "ugc_evidence": "The page explicitly recruits content creators and influencers and provides banners, product images and exclusive coupon codes; no hard creator counts are published, so saturation stays unknown."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('GORUCK', 'https://www.goruck.com', 'American rucking gear company founded in 2008 and based in Jacksonville Beach, Florida, by former Green Beret Jason McCarthy. It builds rucksacks to US Special Forces standards — its original ruck, the GR1 — plus training footwear, apparel and community rucking events.', 'United States', 'published') returning id into bid;
