  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'affiliates@goruck.com', null, 'https://www.goruck.com/pages/affiliates-program', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Everflow', 8, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://storeprofiles.com/store/goruck.', 'https://www.goruck.com/pages/affiliates-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'GORUCK Affiliate Program', 'https://www.goruck.com/pages/affiliates-program', 'https://www.goruck.com/pages/affiliates-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.goruck.com/pages/affiliates-program', 'official_site', 'affiliate', 'GORUCK''s official affiliate page (fetched in full) invites content creators to earn commissions on referred sales through affiliate links, requires an established website and/or social following of at least 1,000 followers/subscribers and 6+ months of consistent content, publishes affiliates@goruck.com for special consideration, and directs athletes to a separate Ambassador program. The official page publishes no percentage and no cap statement, so the cap is honestly unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://storeprofiles.com/store/goruck', 'third_party_listing', 'affiliate', 'StoreProfiles, quoting GORUCK''s own program page, records 8% commission payouts monthly (on monthly commissions of $100 or more) with up to 8% and a 30-day cookie; Skimlinks data for GORUCK EU corroborates 8%.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.everflow.io/post/goruck-strengthens-their-affiliate-program-with-managed-payments', 'affiliate_network', 'affiliate', 'Everflow''s case study states GORUCK runs its affiliate program with Everflow Pay managed payments, with payouts usually within the first week of the month and earnings on purchases through GORUCK''s US and European sites.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://en.wikipedia.org/wiki/GoRuck', 'article', 'company_background', 'Wikipedia describes GORUCK as an American sporting equipment company founded in 2008 and based in Jacksonville Beach, Florida, specialising in rucksacks inspired by those used by US Special Forces, founded by former Green Beret Jason McCarthy.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 17, 15, 13, 7, 5, '{"compensation": "8% per sale (third-party quoting of the program page, corroborated for the EU store) on premium-priced rucks and footwear; a $100 monthly minimum for payout is reported.", "contact_access": "Published affiliate email (affiliates@goruck.com) on the official page, including for applicants below the stated thresholds.", "credibility": "Official program page fetched in full, a platform case study from Everflow, and an established US brand.", "niche_fit": "Rucking is a fast-growing training style and the gear is built for review-led, durability-test UGC.", "opportunity_availability": "Open application, but gated: 1,000+ followers and 6 months of consistent content are required.", "ugc_evidence": "The program is explicitly geared to content creators who review the gear first-hand; no creator counts are published, so saturation stays unknown."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Ergatta', 'https://ergatta.com', 'US connected-rowing brand whose game-based rowing experience runs on the Ergatta Lite and Ergatta Rower with a membership. Alongside a member refer-a-friend scheme, it runs a separate affiliates program for people with a platform, paying commission on rower sales.', 'United States', 'published') returning id into bid;
