  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', 5, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://linkclicky.com/affiliate-program/ergatta/.', 'https://ergatta.com/pages/refer', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Ergatta Affiliates Program (via Impact)', 'https://ergatta.com/pages/refer', 'https://ergatta.com/pages/refer', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ergatta.com/pages/refer', 'official_site', 'affiliate', 'Ergatta''s official page (fetched in full) has a ''Have a Platform? Let''s Partner'' section: ''Reach out to learn more about our Affiliates Program and how you can earn commission by sharing your experience. Email us at affiliates@ergatta.com to get started.'' A separate FAQ answer on the same page says ''If you are interested in becoming an Ergatta Affiliate please email affiliate@ergatta.com'' — both addresses are published on the official page and are recorded as printed. The page''s US$600-per-year maximum applies only to the separate member Refer-a-Friend rewards, not to the affiliate program, so the affiliate cap is honestly unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/ergatta/', 'third_party_listing', 'affiliate', 'LinkClicky lists the Ergatta affiliate program on Impact at 5% per sale. The official page publishes no percentage, so the rate rests on this network listing.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 13, 11, 14, 8, 4, '{"compensation": "5% per sale (Impact listing) is a modest percentage, but it applies to rowers priced from $1,449, so each conversion pays meaningfully.", "contact_access": "Two affiliate emails are published on the brand''s own page (affiliates@ergatta.com and affiliate@ergatta.com, recorded as printed).", "credibility": "The program and its contact route are verified on the brand''s own page; the rate comes from a network listing because the brand does not publish one.", "niche_fit": "A design-led connected rower is a strong fit for home-gym, rowing and connected-fitness creators.", "opportunity_availability": "Live program; joining starts with an email to the affiliate team rather than an open form.", "ugc_evidence": "The brand explicitly invites audience owners to share their experience for commission; no creator counts are published, so saturation stays unknown."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('G Adventures', 'https://www.gadventures.com', 'Canadian-based small-group adventure travel operator founded in 1990, positioning itself as the world leader in adventure travel. Its affiliate program pays commission on confirmed bookings, with an average online order value of $2,600 USD.', 'Canada', 'published') returning id into bid;
