  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'G Adventures Affiliate Program', 'https://www.gadventures.com/affiliate-program/', 'https://www.gadventures.com/affiliate-program/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.gadventures.com/affiliate-program/', 'official_site', 'affiliate', 'G Adventures'' official affiliate page (fetched in full) states ''We typically reward 5% commission for all confirmed sales (average online order value of $2,600 USD)'' with 90-day cookies, publishes the contact email affiliate@gadventures.com, and names both Impact and the Rakuten Affiliate Network as the partners managing payments and sales tracking. No cap statement is published, so the cap is honestly unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://uppromote.com/affiliate-directory/g-adventures/', 'third_party_listing', 'affiliate', 'UpPromote''s directory describes G Adventures as a Canadian-based small-group adventure travel operator founded in 1990 and lists 6% per confirmed online booking, noting some sources cite 5% — the brand''s own published 5% is the rate recorded.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 15, 14, 14, 9, 5, '{"compensation": "5% on the brand''s own page looks low until the $2,600 average order value is applied \u2014 roughly $130 per confirmed booking, with a long 90-day cookie.", "contact_access": "Published affiliate email (affiliate@gadventures.com) on the official program page.", "credibility": "Terms verified on the brand''s own page; a major operator founded in 1990.", "niche_fit": "Small-group adventure tours are exactly what travel creators film and narrate, across hundreds of itineraries.", "opportunity_availability": "Live official program page with network-managed signup through Impact / Rakuten.", "ugc_evidence": "A long-running program (launched in 2008) aimed at partners who sell travel content; no creator counts are published, so saturation stays unknown."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('TourRadar', 'https://www.tourradar.com', 'Marketplace for multi-day organised adventures, founded in 2010 and headquartered in Vienna, Austria, connecting travellers with 2,500+ tour operators and 50,000+ trips. Through its RISE partner programme it runs an Ambassador Program built specifically for travel creators.', 'Austria', 'published') returning id into bid;
