  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Direct (TourRadar RISE)', 7, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.tourradar.com/llp/ambassador.', 'https://www.tourradar.com/llp/ambassador', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'TourRadar Ambassador Program (RISE)', 'https://www.tourradar.com/llp/ambassador', 'https://www.tourradar.com/llp/ambassador', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.tourradar.com/llp/ambassador', 'official_site', 'affiliate', 'TourRadar''s official Ambassador page (fetched in full) states ''You''ll receive 7% commission on every booking made through your link, that''s an average of $180 per booking, based on typical booking values'', and describes the Ambassador Program as ''designed to empower travel creators''. No cap statement is published, so the cap is honestly unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.tourradar.com/rise/earn-money-travel-affiliate-program', 'official_site', 'affiliate', 'TourRadar''s official RISE page (fetched in full) frames RISE as a $1M USD partner fund supporting travellers, creators, guides, advisors and agents; ambassadors earn an average of $180 per first-click booking, while the 10-20% figures on the page apply to advisors/agents, not creators. The fund is a support budget, not an earnings cap. Registration runs through TourRadar''s own dashboard.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.tourradar.com/ai-about-us.txt', 'official_site', 'company_background', 'TourRadar''s own published reference document states it was founded in 2010 and is headquartered in Vienna, Austria, operating as an online travel marketplace and booking intermediary for multi-day tours.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 29, 19, 16, 5, 9, 5, '{"compensation": "7% on every booking through the creator link, stated by the brand as an average of $180 per booking \u2014 strong per-conversion pay for travel.", "contact_access": "No affiliate email is published on the fetched official pages; contact runs through the RISE dashboard registration.", "credibility": "Creator rate and program structure verified on TourRadar''s own pages, fetched in full.", "niche_fit": "A marketplace of 50,000+ multi-day trips means almost any travel itinerary content can carry a bookable link.", "opportunity_availability": "Open registration for the Ambassador Program through TourRadar''s own RISE platform.", "ugc_evidence": "A dedicated creator Ambassador Program with storefront-style promotion and a $1M partner fund behind it \u2014 the strongest creator infrastructure in this batch''s travel picks; no creator counts published, so saturation stays unknown."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Radical Storage', 'https://radicalstorage.com', 'Luggage storage network founded in 2016 and headquartered in Rome, Italy (formerly Bagbnb). Travellers book secure storage at 16,023+ locations in 2,352+ cities, hosted by local business partners, and its affiliate programme invites travel creators to earn on every booking.', 'Italy', 'published') returning id into bid;
