  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Radical Storage Affiliate Programme', 'https://radicalstorage.com/affiliates', 'https://radicalstorage.com/affiliates', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://radicalstorage.com/affiliates', 'official_site', 'affiliate', 'Radical Storage''s official affiliates page (fetched in full) asks ''Property manager, tour operator or travel creator? Travellers need somewhere safe to leave their bags. Recommend Radical Storage and earn on every booking'', cites 16,023+ locations in 2,352+ cities and 4.77/5 from 582,373+ reviews, and says signup takes a minute, is free with no hidden costs, and every request is reviewed by a real person who replies within two working days. The official page publishes no percentage and no cap statement, so the cap is honestly unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/radical-storage/', 'third_party_listing', 'affiliate', 'Lasso lists the Radical Storage affiliate program at 8% per sale.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.affiliates-directory.com/websites/radical-storage', 'affiliate_network', 'affiliate', 'Affiliates-Directory records a standard 8% reward rate via Travelpayouts, rising to 10% for bookings made from February 10 through May 31, 2026; a separate listing (LinkClicky) names CJ Affiliate as a platform, so the network route conflicts while the 8% standard rate agrees across sources.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://radicalstorage.com/travel/is-radical-storage-legit/', 'official_site', 'company_background', 'Radical Storage''s own site states the company was founded in 2016 and is headquartered in Rome, Italy.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 15, 15, 5, 9, 4, '{"compensation": "A standard 8% reward rate on every booking, agreed by two independent listings (with a reported 10% promotional window), though the brand''s own page publishes no percentage.", "contact_access": "No affiliate email published on fetched pages; the application on the official page is the route in, with a human reply promised within two working days.", "credibility": "Program verified on the brand''s own page and rate corroborated across listings; the network route (Travelpayouts vs CJ) conflicts and is flagged.", "niche_fit": "Luggage storage is a universal travel pain point that fits city-guide, itinerary and travel-hack content in 2,352+ cities.", "opportunity_availability": "Free, open signup on the official page with manual review.", "ugc_evidence": "The official page explicitly names travel creators as a target partner type; no creator counts are published, so saturation stays unknown."}'::jsonb);
