  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Factor US Ambassador Program', 'https://www.factor75.com/pages/us-ambassador-program', 'https://www.factor75.com/pages/us-ambassador-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.factor75.com/pages/us-ambassador-program', 'official_site', 'affiliate', 'Factor''s official US Ambassador Program page publishes a tiered flat CPA of $50 per customer at 1-19 customers, rising through $60 (20-49) and $65 (50-99) to $70 at 100+, states the rate increases permanently once each band is hit, that commissions carry a 30-day hold and are paid in USD via Lumanu, and that applications are reviewed personally. It also publishes collab@factor75.com for the Ambassador team. Because pay is a flat per-customer bounty rather than a percentage, commission_rate is recorded as null. No explicit no-cap or unlimited-earnings statement appears on the page, so the cap is recorded as unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://marketplace.referly.so/affiliate-programs/factor-meals', 'affiliate_directory', 'affiliate', 'Referly''s listing describes a separate Factor network program paying a fixed $20 per new customer tracked through CJ Affiliate with a 14-day cookie, and notes some third-party sources cite around $25 - a different track from the official Ambassador tiers, flagged here rather than merged.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://universe.beacons.ai/brands/factor', 'creator_directory', 'creator_saturation', 'Beacons Universe reports posts from 564 creators all time, 70 sponsored posts in the last 12 months and 138 public posts in the last 12 months - a mid-size footprint, neither low (~100 scale) nor high (1,000+), so saturation is recorded as unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.cbinsights.com/company/factor-2', 'article', 'general', 'CB Insights records Factor as founded in 2013, headquartered at Batavia, Illinois, and acquired by HelloFresh Group in November 2020.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 16, 16, 13, 8, 5, '{"niche_fit": "Ready-meal delivery is a core food-creator niche with strong unboxing and meal-prep content angles.", "ugc_evidence": "564 creators all time and 70 sponsored posts in 12 months on Beacons, plus an official ambassador program.", "compensation": "Official tiered flat bounty of $50-$70 per new customer - strong per-conversion pay, recorded as a bounty not a percentage.", "contact_access": "Published collab@factor75.com ambassador-team email plus the official program page.", "opportunity_availability": "Applications are personally reviewed rather than instant, in the US and EU.", "credibility": "Founded 2013 and owned by HelloFresh Group since 2020."}'::jsonb);
