  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.anker.com/become-an-affiliate', 'official_site', 'affiliate', 'Official Anker affiliate page fetched: 8% commission on all transactions, 30-day cookie, a dedicated affiliate manager, contact affiliate@anker.com, and a headline of ''earning up to $10,000 per month'' — that headline is an earnings illustration, not a cap statement, and no ''no cap / unlimited'' wording for the affiliate program appears on the page, so the cap is recorded as unknown. The page names no single network.', 'verified', now());
