  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.anker.com/content-creator?ref=anker-tech', 'official_site', 'ugc_collab', 'Official SuperChargers creator program page fetched: a dedicated long-term creator collaboration track for original video content on mobile charging; requirements are 18+, an active social media account AND an Amazon storefront with a public profile, and residence in the US or Canada; no follower minimum is stated.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://universe.beacons.ai/brands/anker', 'listing', 'ugc_collab', 'Beacons Universe fetched: Anker (based in Changsha, China) has posts from 404 creators all time, 129 public posts in the last 12 months and 8 sponsored posts in the last 12 months (most recent October 6, 2026) — a mid-size creator footprint, neither low nor high enough to record, so saturation is unknown. Note: Anker''s separate consumer referral page uses ''limitless earnings'' language, but that is a customer referral scheme, not the affiliate program, and was not counted as a cap statement.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 17, 16, 14, 8, 5, '{"compensation": "8% on all transactions with a 30-day cookie, published on two official Anker pages; no cap statement is published for the affiliate program (the referral page''s ''limitless'' wording is a different scheme), so cap is unknown", "contact_access": "Dedicated affiliate@anker.com published on the official affiliate page, plus a named dedicated affiliate manager", "credibility": "One of the world''s largest mobile-charging brands (Anker Innovations, Changsha) with global retail distribution", "niche_fit": "Chargers, power banks and everyday tech accessories are staple, demonstrable products for tech and everyday-carry UGC", "opportunity_availability": "Affiliate application is open on the official page; the SuperChargers creator track is gated to US/Canada residents aged 18+ with an Amazon storefront", "ugc_evidence": "A dedicated official creator track (SuperChargers) for long-term original-video collaboration, on top of the affiliate program, with 404 creators all time on Beacons"}'::jsonb);
