  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'DJI Affiliate Program — up to 5% direct (2% drones / 5% handheld), 30-day cookie; US store route up to 8% via Impact; creator contacts published', 'https://u.dji.com/en/quick_start_guide', 'https://u.dji.com/en/quick_start_guide', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://u.dji.com/en/quick_start_guide', 'official_site', 'affiliate', 'Official DJI affiliate guide fetched: the direct program at u.dji.com pays up to 5% — 2% on eligible drone products and 5% on eligible handheld products — with a 30-day cookie, payment 15 days after a sale is confirmed, availability in 46+ countries, and no commission on coupon orders or DJI Select member orders. Application is by email sign-up on u.dji.com with approval by email. ''Up to 5%'' is a rate ceiling, not an earnings cap, and no cap statement is published, so the cap is unknown. The recorded 5% is the headline maximum of this official direct program.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.djiusa.com/pages/affiliate-program', 'official_site', 'affiliate', 'DJI USA Store affiliate page fetched: a separate US-store route via Impact paying up to 8% on eligible sales with a 30-day cookie, rates varying by category, campaign and partner type, welcoming creators, publishers and review sites, with service@djiusa.com published. djiusa.com is a distinct store site from dji.com, so this is recorded as a second route, not the headline rate.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.dji.com/contact?site=enterprise&from=footer', 'official_site', 'contact', 'Official DJI contact page fetched: publishes dedicated creator-economy contacts — Influencer Partnership: KOL@influencer.dji.com; Creator Collaboration: global-creator@dji.com; Media Inquiries: pr@dji.com.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://universe.beacons.ai/brands/dji', 'listing', 'ugc_collab', 'Beacons Universe fetched: DJI (based in Shenzhen, China) has posts from 2,247 creators all time, 1,928 public posts in the last 12 months, 39 sponsored posts in the last 12 months and 147 creators posted in the last 30 days — hard evidence of a very large creator footprint, so saturation is recorded as high.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 16, 13, 15, 8, 5, '{"compensation": "Direct program pays up to 5% (2% drones / 5% handheld) with a 30-day cookie; the separate DJI USA Store route pays up to 8% via Impact; both are rate ceilings and no earnings-cap statement is published, so cap is unknown", "contact_access": "Three dedicated published emails on the official contact page \u2014 KOL@influencer.dji.com, global-creator@dji.com and pr@dji.com \u2014 the strongest contact access in this batch", "credibility": "The dominant global drone and camera-gimbal maker, headquartered in Shenzhen since 2006", "niche_fit": "Drones and action cameras are creator-native products \u2014 the buyers film for a living, making DJI a flagship tech UGC brand", "opportunity_availability": "Open application on u.dji.com across 46+ countries with no follower minimum stated; coupon and DJI Select orders earn nothing", "ugc_evidence": "2,247 creators all time and 39 sponsored posts in the last 12 months on Beacons, plus published influencer-partnership and creator-collaboration routes on the official contact page"}'::jsonb);
