  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://universe.beacons.ai/brands/open-farm', 'listing', 'ugc_collab', 'Beacons Universe fetched (updated November 20, 2026): Open Farm, based in Toronto, Canada, has posts from 446 creators all time, 921 public posts in the last 12 months, 157 sponsored posts in the last 12 months and 59 creators posted in the last 30 days — an established mid-size creator program; 446 creators is not small in absolute terms, so saturation is honestly recorded as unknown rather than low.', 'publicly_reported', now());
