  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/59049', 'listing', 'affiliate', 'Awin merchant profile fetched: Furbo pays ''10% commission sitewide'' (dropping to 5% for coupon/deal sites per a program roundup that read the same profile), with average order value over $120 and a 30-day cookie for the US and Canada; the profile explicitly welcomes content creators, pet bloggers and tech reviewers. No cap statement appears in any fetched source, so the cap is recorded as unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/furbo/', 'listing', 'affiliate', 'Lasso''s Furbo listing fetched: 5% per sale with a 30-day cookie — conflicting with the Awin profile''s 10% sitewide; Referly''s marketplace likewise reports 5% CPS across ShareASale/Awin/FlexOffers routes. The 10% Awin network-profile figure is recorded as the headline rate, with the 5% figures documented here.', 'publicly_reported', now());
