  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 13, 15, 7, 9, 4, '{"compensation": "10% sitewide per the Awin network profile on $120+ average orders with a 30-day cookie (5% for coupon/deal sites); Lasso and Referly report 5% on other routes \u2014 the conflict is documented; no cap statement published, so cap is unknown", "contact_access": "No partnerships or affiliate email was published on any fetched page; joining is via the Awin/ShareASale network listings", "credibility": "Tomofun is an established pet-tech company founded in Taiwan (HQ Taipei) whose Furbo camera is a category bestseller in multiple countries", "niche_fit": "A treat-tossing pet camera is one of the most demonstrable pet-tech products \u2014 built for separation-anxiety, check-in and funny-moment UGC", "opportunity_availability": "Open network applications, accepted worldwide per Referly, with no minimum payout reported", "ugc_evidence": "The Awin profile explicitly recruits content creators, pet bloggers and tech reviewers, but no Beacons creator count was found, so evidence is program-led and saturation stays unknown"}'::jsonb);
