  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.carawayhome.com/pages/affiliate', 'official_site', 'affiliate', 'Official Caraway affiliate page fetched: aimed at website/blog owners, ''We pay a commission on every sale from our website'', with Apply Now linking to the program on Impact (app.impact.com). The page publishes NO percentage, and no cap statement, so both the rate (see conflicting listings below) and the cap are honestly recorded from listings/unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.carawayhome.com/pages/ambassadors', 'official_site', 'ugc_collab', 'Official Caraway Ambassador Program page fetched: a dedicated creator track for creators with 10k+ followers offering free products, early access and commission with a monthly posting requirement, plus a Fan Rewards tier with no minimum requirement paying commission on referrals; sign-up runs through Roster (apply.getroster.com). A Roster case study reports roughly 4,000+ active ambassadors and says the follower minimum was recently lowered from 10,000 to 5,000 — conflicting with the official page''s current 10k+ table, so both are reported.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/caraway-home/', 'listing', 'affiliate', 'LinkClicky listing fetched: Caraway Home runs on Impact at 8% per sale (listing updated March 18, 2024). Lasso separately advertises ''up to 3.75%'' with a 14-day cookie. Because the official page publishes no rate and the two fetched listings conflict (8% vs up to 3.75%), the recorded commission rate is null with both figures documented here.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://universe.beacons.ai/brands/caraway-home', 'listing', 'ugc_collab', 'Beacons Universe fetched: Caraway Home (based in New York, United States) has posts from 1,288 creators all time, 869 public posts in the last 12 months and 40 sponsored posts in the last 12 months — together with Roster''s ~4,000+ active ambassadors, hard evidence of a large creator program, so saturation is recorded as high.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 19, 8, 7, 8, 5, '{"compensation": "The official page publishes no percentage and fetched listings conflict (8% per LinkClicky vs up to 3.75% per Lasso), so the rate is recorded as null with the conflict documented; no cap statement published, so cap is unknown", "contact_access": "No partnerships or affiliate email was published on the fetched official pages; joining is via Impact or the Roster ambassador application", "credibility": "Established New York-based DTC cookware brand with major retail presence", "niche_fit": "Colourful non-toxic cookware is a staple of cooking, kitchen-reset and healthy-home UGC", "opportunity_availability": "Ambassador track requires 10k+ followers (Roster reports it was lowered to 5,000); Fan Rewards has no minimum", "ugc_evidence": "Two official creator routes \u2014 an Impact affiliate program and a dedicated Ambassador Program (10k+ followers, free product, monthly posting) plus a no-minimum Fan Rewards tier \u2014 with 1,288 creators on Beacons and ~4,000+ ambassadors per Roster"}'::jsonb);
