  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://uppromote.com/affiliate-directory/farmers-dog/', 'listing', 'affiliate', 'UpPromote directory fetched: ''typically $50 flat fee per new subscription sale'' via Impact with a $10 minimum payout. Other fetched listings conflict further — a flat 10% (PostAffiliatePro/Brandid) and an outlier $100 per qualified sale (Creator Hero) — so published figures irreconcilably conflict ($40 / $50 / 10% / $100, flat vs percentage) and the recorded rate is null with all figures documented.', 'publicly_reported', now());
